(()=>{'use strict';const base='https://kenny-studio-orders-test.onrender.com',key='kenny-favourite-packages-v1';let fav=[];try{fav=JSON.parse(localStorage.getItem(key)||'[]')}catch{}if(!Array.isArray(fav))fav=[];const packs=[['essential','Essential Landing Page / 基础落地页'],['signature','Signature Landing Page / 品牌落地页'],['personal','Personal Brand Website / 个人品牌网站'],['business','Business Website / 企业网站'],['ecommerce','E-commerce Website / 电商网站']];fav=fav.filter(id=>packs.some(p=>p[0]===id));const paths={search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',user:'M5 21v-3a7 7 0 0 1 14 0v3 M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bag:'M5 7h14l2 14H3z M8 8V6a4 4 0 0 1 8 0v2'};function icon(n){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[n]+'"/></svg>'}const el=(t,text)=>{const e=document.createElement(t);if(text)e.textContent=text;return e};let bar=el('div');bar.id='kenny-quick-actions';bar.setAttribute('role','group');bar.setAttribute('aria-label','快捷入口 / Quick actions');function dialog(title){const d=el('dialog');d.className='kenny-welcome kenny-quick-dialog';const h=el('h2',title);d.setAttribute('aria-label',title);const x=el('button','×');x.type='button';x.className='kenny-welcome-close';x.setAttribute('aria-label','关闭 / Close');x.onclick=()=>d.close();d.append(x,h);document.body.append(d);d.addEventListener('close',()=>d.remove());return d}function favourites(){const d=dialog('收藏套餐 / Saved packages'),intro=el('p','点击爱心保存感兴趣的套餐，准备好后加入购物篮。Saved on this browser.');d.append(intro);for(const [id,name]of packs){const row=el('div');row.className='kenny-saved-row';const heart=el('button',fav.includes(id)?'♥':'♡');heart.type='button';heart.setAttribute('aria-label','收藏 / Save '+name);heart.setAttribute('aria-pressed',String(fav.includes(id)));heart.onclick=()=>{fav=fav.includes(id)?fav.filter(v=>v!==id):[...fav,id];try{localStorage.setItem(key,JSON.stringify(fav))}catch{}heart.textContent=fav.includes(id)?'♥':'♡';heart.setAttribute('aria-pressed',String(fav.includes(id)));badge.textContent=String(fav.length)};const link=el('a',name+' ↗');link.href=base+'/?add='+id;row.append(heart,link);d.append(row)}d.showModal()}function search(){const d=dialog('搜索服务与套餐 / Search'),input=el('input'),results=el('div');input.type='search';input.placeholder='搜索，例如：SEO、企业网站、价格';input.setAttribute('aria-label','搜索服务与套餐');results.className='kenny-search-results';const pages=[['Website design 网站设计','/services/website-design/'],['Google Ads 广告管理','/services/google-ads-management/'],['SEO 搜索优化','/services/seo/'],['Pricing 套餐与价格','/pricing/'],['Policy 项目条款','/policy/'],...packs.map(([id,name])=>[name,base+'/?add='+id])];function draw(){results.replaceChildren();const q=input.value.toLowerCase().trim(),matches=pages.filter(([name])=>name.toLowerCase().includes(q));for(const [name,href]of matches){const a=el('a',name+' ↗');a.href=href;results.append(a)}if(!matches.length)results.append(el('p','没有匹配结果 / No matching services'))}input.oninput=draw;d.append(input,results);draw();d.showModal();input.focus()}function control(n,label,href,action){const e=el(href?'a':'button');e.innerHTML=icon(n);e.title=label;e.setAttribute('aria-label',label);if(href)e.href=href;else{e.type='button';e.onclick=action}bar.append(e);return e}control('search','搜索 / Search',null,search);control('user','我的账号 / My account',base+'/account');const saved=control('heart','收藏套餐 / Saved packages',null,favourites),badge=el('span',String(fav.length));badge.className='kenny-saved-count';saved.append(badge);const bag=control('bag','购物篮 / Basket',base+'/');bag.append(el('span','Bag'));function mount(){const host=document.querySelector('.header-tools')||document.querySelector('.service-tools');if(host&&!host.contains(bar))host.prepend(bar)}mount();new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});})();